import{_ as a,o,c as i,am as e}from"./chunks/framework._FJXuPhs.js";const p=JSON.parse('{"title":"同事分享-ZGC 调优建议","description":"","frontmatter":{"title":"同事分享-ZGC 调优建议","excerpt":"摘要","date":"2025-08-20 19:31:38","updated":"2025-08-20 19:31:38"},"headers":[],"relativePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/同事分享-ZGC 调优建议.md","filePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/同事分享-ZGC 调优建议.md","lastUpdated":null}'),t={name:"基础/多线程并发与JVM原理/JVM入门_基础概念/同事分享-ZGC 调优建议.md"};function r(n,l,s,c,d,g){return o(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="zgc垃圾回收器-原理与实践优化" tabindex="-1">ZGC垃圾回收器：原理与实践优化 <a class="header-anchor" href="#zgc垃圾回收器-原理与实践优化" aria-label="Permalink to &quot;ZGC垃圾回收器：原理与实践优化&quot;">​</a></h1><h2 id="一、问题背景" tabindex="-1">一、问题背景 <a class="header-anchor" href="#一、问题背景" aria-label="Permalink to &quot;一、问题背景&quot;">​</a></h2><p>Hinton 测试环境发生 OOM 连续重启，经过排查是因为堆内存超出容器内存限制，导致容器的 OOM 直接被杀死，因此也没有机会执行 java-dump。</p><p>在排查过程中发现一个奇妙的现象：年轻代对象总是在临近内存打满时才触发回收（如图1所示）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250820193206.png" alt="image.png"></p><p>在重新配置容器内存解决 OOM 问题后，开始排查出现上述现象的原因。</p><h2 id="二、zgc背景" tabindex="-1">二、ZGC背景 <a class="header-anchor" href="#二、zgc背景" aria-label="Permalink to &quot;二、ZGC背景&quot;">​</a></h2><h3 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h3><p>不同于 G1，JDK 21 之前 ZGC 是无分代的，到 JDK 21 起才正式支持分代，并且计划在 JDK 23 成为默认垃圾回收器，在此之前都需要手动指定使用分代 ZGC（<code>-XX:+UseZGC</code>）。</p><p><strong>TIPS</strong>：启动分代 ZGC 参数（<code>-XX:+ZGenerational</code>）</p><h3 id="分代回收理论基础" tabindex="-1">分代回收理论基础 <a class="header-anchor" href="#分代回收理论基础" aria-label="Permalink to &quot;分代回收理论基础&quot;">​</a></h3><p>分代回收主要是基于两个假说：</p><ul><li><strong>弱分代假说</strong>（Weak Generational Hypothesis）：绝大多数对象是朝生夕死，在年轻时死亡。</li><li><strong>强分代假说</strong>（Strong Generational Hypothesis）：熬过多次垃圾回收的老年对象更难死亡。</li></ul><p>收集年轻对象消耗的资源较少，回收内存较多；收集老年对象消耗的资源较多，回收内存较少。</p><h3 id="分代-zgc-generational-zgc-特性" tabindex="-1">分代 ZGC（Generational ZGC）特性 <a class="header-anchor" href="#分代-zgc-generational-zgc-特性" aria-label="Permalink to &quot;分代 ZGC（Generational ZGC）特性&quot;">​</a></h3><ol><li><p><strong>极低的停顿时间</strong>：其GC暂停通常在微秒级，大幅优于 G1（通常在几十到几百毫秒），并且分代 ZGC 的停顿时间不受堆大小影响。</p></li><li><p><strong>全并发</strong>：通过染色指针+读写屏障的支持，实现几乎所有阶段（标记、整理/压缩、对象回收）都和应用线程并发执行，STW 次数少，停顿时间短，最大程度保证业务不中断。</p></li><li><p><strong>自适应触发</strong>：默认不进行任何配置情况下，ZGC 基于内存余量和申请速度自适应判断是否触发GC。当 JVM 检测到剩余可用堆不足以撑到下一次 GC，或者分配速率快于回收速率（年轻代空间即将耗尽）时主动发起垃圾回收，以避免因为分配失败导致应用线程阻塞。全堆内存达到一定阈值，自动决定是否触发回收，也可以通过参数手动干预或配置定时回收。</p></li></ol><h3 id="为什么出现背景中描述的现象" tabindex="-1">为什么出现背景中描述的现象 <a class="header-anchor" href="#为什么出现背景中描述的现象" aria-label="Permalink to &quot;为什么出现背景中描述的现象&quot;">​</a></h3><ol><li><strong>没有开启提前回收和定时回收</strong>：每次都是被动快打满才回收</li><li><strong>测试环境对象申请速度慢</strong>：内存稳步增长，几乎半小时才达到一次阈值</li></ol><h2 id="三、zgc优势" tabindex="-1">三、ZGC优势 <a class="header-anchor" href="#三、zgc优势" aria-label="Permalink to &quot;三、ZGC优势&quot;">​</a></h2><ol><li><p><strong>大堆高性能</strong>：能够支撑极大堆的 GC 而不会延长停顿时间（单次不超过1ms），稳定且性能高。</p></li><li><p><strong>工业实践证明</strong>：转转和京东实践表明：</p><ul><li>CPU 平均使用率上涨 20%</li><li>GC Allocation Stall 降低 85%</li><li>QPS 提升15%</li><li>最大内存使用率基本不变</li><li>TP 响应时间降低</li></ul></li><li><p><strong>超大内存支持</strong>：X86_64 处理器地址线有 48 条，除去 4 位染色指针，剩余 44 位可用对象地址，理论上支持 16TB 内存（但官方宣称最大支持 4TB，目的是平衡性能、稳定性和实际需求）</p></li><li><p><strong>低延迟场景最佳选择</strong>：适用于追求极致低延迟的应用场景、对业务的影响极小</p></li><li><p><strong>自调优能力强</strong>：绝大多数场景无需复杂参数配置</p></li></ol><h2 id="四、zgc参数调优" tabindex="-1">四、ZGC参数调优 <a class="header-anchor" href="#四、zgc参数调优" aria-label="Permalink to &quot;四、ZGC参数调优&quot;">​</a></h2><h3 id="核心参数" tabindex="-1">核心参数 <a class="header-anchor" href="#核心参数" aria-label="Permalink to &quot;核心参数&quot;">​</a></h3><ol><li><p><strong><code>-XX:+ZProactive</code></strong>：在尚未发生内存压力前，根据分配趋势主动提前发起一次并发回收，避免被动等待内存接近填满。</p></li><li><p><strong><code>-XX:ZAllocationSpikeTolerance=2</code></strong>：控制 ZGC 对内存分配高峰（allocation spike）的敏感度，表示一般情况下，分配速率可以有两倍的暂时抖动被容忍。</p><ul><li>如果想要 JVM 更加积极和频繁地触发 GC，可以调小该值</li><li>如果存在瞬时的剧烈高峰，可适当调大该值，让 ZGC 对突发分配更容忍，不至于频繁 GC</li><li>但风险是可能老年代更快耗尽，或者最终发生 Full GC</li></ul></li><li><p><strong><code>-XX:ZCollectionInterval=30</code></strong>：每 30 秒触发一次 GC，可以避免长时间不触发GC导致的内存堆积问题。</p></li><li><p><strong><code>-XX:ConcGCThreads=4 -XX:-UseDynamicNumberOfGCThreads</code></strong>：</p><ul><li>固定 GC 线程数为4个</li><li>不开启动态 GC 线程数</li><li>稳定 GC 对系统资源的占用</li><li>减少 GC 对正常业务线程的竞争</li></ul></li></ol><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250820193800.png" alt="image.png"></p><h3 id="内存分配相关参数" tabindex="-1">内存分配相关参数 <a class="header-anchor" href="#内存分配相关参数" aria-label="Permalink to &quot;内存分配相关参数&quot;">​</a></h3><ol start="5"><li><p><strong><code>-XX:+UseNUMA</code></strong>：在NUMA架构的服务器上优化内存分配</p></li><li><p><strong><code>-XX:ZUncommitDelay=300</code></strong>：设置内存释放延迟，单位为秒，默认300秒</p></li><li><p><strong><code>-XX:ZUncommit=false/true</code></strong>：是否允许ZGC将未使用的内存返还给操作系统</p></li></ol><h3 id="调试和监控参数" tabindex="-1">调试和监控参数 <a class="header-anchor" href="#调试和监控参数" aria-label="Permalink to &quot;调试和监控参数&quot;">​</a></h3><ol start="8"><li><p><strong><code>-XX:+UnlockDiagnosticVMOptions -XX:+ZStatisticsForceTrace</code></strong>：强制ZGC输出更详细的统计信息，用于调试</p></li><li><p><strong><code>-Xlog:gc*=debug:file=gc.log:time,pid,tags:filecount=10,filesize=100m</code></strong>：详细GC日志配置</p></li></ol><h2 id="五、实战经验与最佳实践" tabindex="-1">五、实战经验与最佳实践 <a class="header-anchor" href="#五、实战经验与最佳实践" aria-label="Permalink to &quot;五、实战经验与最佳实践&quot;">​</a></h2><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ol><li><strong>低延迟敏感型应用</strong>：如金融交易、在线游戏、实时数据处理等对响应时间有严格要求的系统</li><li><strong>大内存应用</strong>：8GB以上堆内存的应用可以考虑使用ZGC</li><li><strong>高吞吐量与低延迟兼顾</strong>：虽然吞吐量略低于Parallel GC，但差距不大，同时可提供极低的延迟</li></ol><h3 id="不适用场景" tabindex="-1">不适用场景 <a class="header-anchor" href="#不适用场景" aria-label="Permalink to &quot;不适用场景&quot;">​</a></h3><ol><li><strong>内存受限系统</strong>：ZGC内存开销较大，不适合内存较小的环境</li><li><strong>CPU受限系统</strong>：ZGC会增加约15-20%的CPU使用率</li><li><strong>极端吞吐量优先场景</strong>：如果只关心吞吐量而不关心延迟，Parallel GC可能更合适</li></ol><h3 id="实施建议" tabindex="-1">实施建议 <a class="header-anchor" href="#实施建议" aria-label="Permalink to &quot;实施建议&quot;">​</a></h3><ol><li><strong>循序渐进</strong>：对于生产环境，建议先在测试/预发布环境充分验证ZGC表现</li><li><strong>监控到位</strong>：上线ZGC后应重点监控JVM GC指标、系统CPU使用率、应用延迟等关键指标</li><li><strong>容器环境注意事项</strong>：确保容器内存限制大于JVM堆内存+额外开销（通常为堆内存的15%）</li><li><strong>调参谨慎</strong>：除非出现明显问题，否则不建议过多调整ZGC参数，其自适应能力已经很强</li><li><strong>升级路径</strong>：堆不大且有G1调优经验的情况下，建议还是使用G1，等ZGC有更多更佳实践之后再考虑迁移</li></ol><h2 id="六、结论与建议" tabindex="-1">六、结论与建议 <a class="header-anchor" href="#六、结论与建议" aria-label="Permalink to &quot;六、结论与建议&quot;">​</a></h2><p>针对本次问题，建议采取以下优化措施：</p><ol><li>启用ZGC提前回收机制：<code>-XX:+ZProactive</code></li><li>设置定期回收：<code>-XX:ZCollectionInterval=30</code>（根据业务特性调整）</li><li>合理设置容器内存限制：确保至少比Java堆内存大20%</li><li>在实际业务负载下进行压力测试，验证优化效果</li><li>适当调整<code>ZAllocationSpikeTolerance</code>参数，根据内存分配模式找到最佳平衡点</li></ol><p>ZGC作为新一代低延迟垃圾收集器，具有极大的潜力，特别是在JDK 21引入分代ZGC后，性能和适用性都得到了显著提升。</p><p>随着更多企业实践的积累和官方的持续优化，ZGC有望在JDK 23成为默认垃圾收集器，成为Java应用的首选GC方案。</p>',40)])])}const G=a(t,[["render",r]]);export{p as __pageData,G as default};
